    function createClone(address collateral, address debt, address owner) external returns (address clone) {
        bytes memory data = abi.encodePacked(owner, collateral, debt, address(this));
        // Use the clone routine from ClonesWithImmutableArgs
        clone = implementation.clone(data);
    }
}

